const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

// 1. Extraer datos del webhook de forma segura
let webhookBody = {};
try {
  const wh = $('Webhook').first().json;
  webhookBody = wh.body || wh;
} catch (e) {
  try {
    const inp = $input.first().json;
    webhookBody = inp.body || inp;
  } catch (e2) {
    webhookBody = {};
  }
}

const conversation = webhookBody.conversation || {};
const account = webhookBody.account || {};
const inbox = webhookBody.inbox || {};
const conversationId = conversation.id || webhookBody.id || 13;
const accountId = account.id || 1;
const content = webhookBody.content || '';
const channel = conversation.channel || inbox.channel_type || '';
let labels = Array.isArray(conversation.labels) ? conversation.labels : [];
let inboxId = Number(inbox.id || conversation.inbox_id || 0);

// 2. Consultar conversación, mensajes y contacto en Chatwoot API
let convData = {};
let contactData = {};
let contactId = null;

try {
  convData = await this.helpers.httpRequest({
    method: 'GET',
    url: chatwootBase + '/conversations/' + conversationId,
    headers: { 'api_access_token': chatwootToken },
    json: true
  });
  if (convData) {
    inboxId = Number(convData.inbox_id || inboxId || 0);
    if (Array.isArray(convData.labels)) {
      labels = convData.labels;
    }
    contactId = convData.meta?.sender?.id || convData.contact_id;
  }
} catch (e) {}

// Obtener todos los mensajes de la conversación
let allMessages = [];
try {
  const msgsRes = await this.helpers.httpRequest({
    method: 'GET',
    url: chatwootBase + '/conversations/' + conversationId + '/messages',
    headers: { 'api_access_token': chatwootToken },
    json: true
  });
  if (msgsRes && Array.isArray(msgsRes.payload)) {
    allMessages = msgsRes.payload;
  }
} catch (e) {}

// 3. ROLLING DEBOUNCE (espera dinámica de 5 segundos con reinicio por cada nuevo escrito):
const incomingMsgs = allMessages.filter(m => m.message_type === 0 || (m.sender && m.sender.type === 'user'));
let lastIncomingTimestamp = 0;
if (incomingMsgs.length > 0) {
  const lastMsg = incomingMsgs[incomingMsgs.length - 1];
  lastIncomingTimestamp = lastMsg.created_at ? (lastMsg.created_at * 1000) : 0;
}

const nowMs = Date.now();
const elapsedMs = nowMs - lastIncomingTimestamp;

// Si el último escrito del cliente llegó hace menos de 4.5 segundos, significa que llegó otro mensaje
// mientras esta ejecución esperaba sus 5s. Cedemos el turno a la ejecución más reciente para evitar respuestas duplicadas.
if (lastIncomingTimestamp > 0 && elapsedMs < 4500) {
  return [{
    json: {
      conversation_id: conversationId,
      skip_ai_response: true,
      reason: 'rolling_debounce_yield_to_newer_message'
    }
  }];
}

if (contactId) {
  try {
    const ctRes = await this.helpers.httpRequest({
      method: 'GET',
      url: chatwootBase + '/contacts/' + contactId,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    contactData = ctRes?.payload || {};
  } catch (e) {}
}

const isHuman = labels.includes('human');

// Auto-asignación a Agent 3 y Team 1
try {
  const currentAssigneeId = convData?.meta?.assignee?.id;
  const currentTeamId = convData?.meta?.team?.id;
  if (currentAssigneeId !== 3 || currentTeamId !== 1) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: chatwootBase + '/conversations/' + conversationId + '/assignments',
      headers: {
        'api_access_token': chatwootToken,
        'Content-Type': 'application/json'
      },
      body: { assignee_id: 3, team_id: 1 },
      json: true
    });
  }
} catch (e) {}

// 4. Inboxes y etiquetas
const isTVTotal24 = (inboxId === 10 || inboxId === 13 || inboxId === 15 || inboxId === 16 || inboxId === 19);
const brand = isTVTotal24 ? 'tvtotal24' : 'totaltvusa';

let updatedLabels = [...labels];
let needsLabelUpdate = false;

if (updatedLabels.includes('autoclosed')) {
  updatedLabels = updatedLabels.filter(l => l !== 'autoclosed');
  needsLabelUpdate = true;
}

if (isTVTotal24) {
  if (updatedLabels.includes('funnel-totaltv-usa')) {
    updatedLabels = updatedLabels.filter(l => l !== 'funnel-totaltv-usa');
    needsLabelUpdate = true;
  }
  if (!updatedLabels.includes('funnel-totaltv-latina')) {
    updatedLabels.push('funnel-totaltv-latina');
    needsLabelUpdate = true;
  }
  if (inboxId === 19) {
    updatedLabels = updatedLabels.filter(l => l !== 'channel-whatsapp');
    if (!updatedLabels.includes('channel-whatsapp-lite')) {
      updatedLabels.push('channel-whatsapp-lite');
      needsLabelUpdate = true;
    }
  } else if (inboxId === 16 && !updatedLabels.includes('channel-facebook')) {
    updatedLabels.push('channel-facebook');
    needsLabelUpdate = true;
  } else if (inboxId === 13 && !updatedLabels.includes('channel-instagram')) {
    updatedLabels.push('channel-instagram');
    needsLabelUpdate = true;
  } else if (inboxId === 10 && !updatedLabels.includes('channel-telegram')) {
    updatedLabels.push('channel-telegram');
    needsLabelUpdate = true;
  } else if (inboxId === 15 && !updatedLabels.includes('channel-tiktok')) {
    updatedLabels.push('channel-tiktok');
    needsLabelUpdate = true;
  }
} else {
  if (updatedLabels.includes('funnel-totaltv-latina')) {
    updatedLabels = updatedLabels.filter(l => l !== 'funnel-totaltv-latina');
    needsLabelUpdate = true;
  }
  if (!updatedLabels.includes('funnel-totaltv-usa')) {
    updatedLabels.push('funnel-totaltv-usa');
    needsLabelUpdate = true;
  }
  if (inboxId === 18) {
    if (!updatedLabels.includes('channel-whatsapp-lite')) {
      updatedLabels.push('channel-whatsapp-lite');
      needsLabelUpdate = true;
    }
  } else if (inboxId === 17 || channel.toLowerCase().includes('facebook')) {
    if (!updatedLabels.includes('channel-facebook')) {
      updatedLabels.push('channel-facebook');
      needsLabelUpdate = true;
    }
  } else if (inboxId === 14 && !updatedLabels.includes('channel-instagram')) {
    updatedLabels.push('channel-instagram');
    needsLabelUpdate = true;
  } else if (inboxId === 6 && !updatedLabels.includes('channel-telegram')) {
    updatedLabels.push('channel-telegram');
    needsLabelUpdate = true;
  } else if (inboxId === 4 && !updatedLabels.includes('channel-whatsapp')) {
    updatedLabels.push('channel-whatsapp');
    needsLabelUpdate = true;
  }
}

if (needsLabelUpdate) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: chatwootBase + '/conversations/' + conversationId + '/labels',
      headers: {
        'api_access_token': chatwootToken,
        'Content-Type': 'application/json'
      },
      body: { labels: updatedLabels },
      json: true
    });
  } catch (e) {}
}

// 5. AGREGACIÓN DE MENSAJES Y ADJUNTOS NO ATENDIDOS DESDE EL ÚLTIMO MENSAJE DEL ASISTENTE
let lastOutgoingTimestamp = 0;
for (let i = allMessages.length - 1; i >= 0; i--) {
  if (allMessages[i].message_type === 1) {
    lastOutgoingTimestamp = allMessages[i].created_at ? (allMessages[i].created_at * 1000) : 0;
    break;
  }
}

const unhandledIncoming = incomingMsgs.filter(m => {
  const mTime = m.created_at ? (m.created_at * 1000) : 0;
  return mTime > lastOutgoingTimestamp;
});

let combinedTextParts = [];
let collectedImageAttachments = [];

if (unhandledIncoming.length > 0) {
  for (const msg of unhandledIncoming) {
    if (msg.content && msg.content.trim()) {
      combinedTextParts.push(msg.content.trim());
    }
    if (Array.isArray(msg.attachments)) {
      for (const att of msg.attachments) {
        if (att.file_type === 'image' || (att.content_type && att.content_type.startsWith('image')) || (att.data_url && /\.(jpeg|jpg|png|webp)/i.test(att.data_url))) {
          collectedImageAttachments.push(att);
        }
      }
    }
  }
}

const webhookAtts = webhookBody.attachments || (webhookBody.conversation?.messages?.[0]?.attachments) || [];
for (const att of webhookAtts) {
  if (att.file_type === 'image' || (att.content_type && att.content_type.startsWith('image')) || (att.data_url && /\.(jpeg|jpg|png|webp)/i.test(att.data_url))) {
    if (!collectedImageAttachments.some(a => a.data_url === att.data_url)) {
      collectedImageAttachments.push(att);
    }
  }
}

let fullContent = combinedTextParts.join('\n');
if (!fullContent && content) {
  fullContent = content;
}

// 6. HISTORIAL DE CONVERSACIÓN RECIENTE DE CHATWOOT (mantiene contexto completo tras minutos u horas)
const visibleMessages = allMessages.filter(m => !m.private && (m.message_type === 0 || m.message_type === 1));
const historyPool = visibleMessages.filter(m => !unhandledIncoming.some(u => u.id === m.id));

let historyBlock = '';
if (historyPool.length > 0) {
  const recentHistory = historyPool.slice(-8);
  const nowSec = Math.floor(nowMs / 1000);
  const historyLines = [];

  for (const m of recentHistory) {
    const sender = (m.message_type === 0) ? 'Cliente' : 'Asistente';
    let text = (m.content || '').replace(/\n+/g, ' ').trim();
    if (text.length > 160) text = text.slice(0, 157) + '...';
    const atts = Array.isArray(m.attachments) ? m.attachments : [];
    const attDesc = atts.length > 0 ? ` [Adjuntó ${atts.length} imagen(es)]` : '';
    const diffSec = nowSec - (m.created_at || nowSec);
    let timeStr = 'hace unos segs';
    if (diffSec >= 86400) timeStr = `hace ${Math.floor(diffSec / 86400)}d`;
    else if (diffSec >= 3600) timeStr = `hace ${Math.floor(diffSec / 3600)}h`;
    else if (diffSec >= 60) timeStr = `hace ${Math.floor(diffSec / 60)}m`;

    if (!text && attDesc) text = '[Mensaje con adjunto]';
    if (text || attDesc) {
      historyLines.push(`• [${sender} (${timeStr})]: ${text}${attDesc}`);
    }
  }

  if (historyLines.length > 0) {
    historyBlock = `[HISTORIAL RECIENTE DE LA CONVERSACIÓN EN CHATWOOT:\n${historyLines.join('\n')}\nINSTRUCCIÓN DE CONTEXTO: Utiliza este historial previo para entender el contexto activo del cliente, dar seguimiento a acuerdos de pago, planes o fallas anteriores, y NO saludar como si fuera el primer mensaje si la conversación ya estaba en curso.]\n\n`;
  }
}

let hasImage = false;
let base64Image = '';
let mediaType = 'image/jpeg';

if (collectedImageAttachments.length > 0) {
  const imageUrl = collectedImageAttachments[0].data_url || collectedImageAttachments[0].thumb_url;
  if (imageUrl) {
    if (imageUrl.toLowerCase().includes('.png')) mediaType = 'image/png';
    else if (imageUrl.toLowerCase().includes('.webp')) mediaType = 'image/webp';
    try {
      const imgBuffer = await this.helpers.httpRequest({
        url: imageUrl,
        encoding: 'arraybuffer'
      });
      base64Image = Buffer.from(imgBuffer).toString('base64');
      if (base64Image) {
        hasImage = true;
      }
    } catch (e) {}
  }
}

let rawPhone = contactData.phone_number || convData?.meta?.sender?.phone_number || '';
if (!rawPhone && contactData.identifier) {
  const ident = String(contactData.identifier);
  if (ident.includes('@s.whatsapp.net') || ident.includes('@c.us') || /^\+?\d[\d\s-]{6,}$/.test(ident)) {
    rawPhone = ident;
  }
}

const contactPhone = String(rawPhone || '').trim();
const contactEmail = String(contactData.email || convData?.meta?.sender?.email || '').trim();
const contactName = String(contactData.name || convData?.meta?.sender?.name || '').trim();
const contactBio = String(contactData.additional_attributes?.description || '').trim();
const contactAdditionalAttrs = contactData.additional_attributes || convData?.meta?.sender?.additional_attributes || {};
const contactCustomAttrs = contactData.custom_attributes || convData?.meta?.sender?.custom_attributes || {};
const contactCompanyName = String(contactAdditionalAttrs.company_name || '').trim();
const contactUsuario = String(contactCustomAttrs.usuario || contactAdditionalAttrs.usuario || '').trim();

const isAlreadyLeadsGanados = updatedLabels.includes('stage-leads-ganados') || updatedLabels.includes('leads-ganados');
const canBypassSheet = isAlreadyLeadsGanados && Boolean(contactCompanyName) && Boolean(contactBio);

const isNumericName = /^\+?\d[\d\s-]{5,}$/.test(String(contactName || '').trim());
const isValidPersonName = contactName && contactName !== 'Customer' && contactName !== 'Desconocido' && !isNumericName;

let clientContextPrefix = '';
if (isAlreadyLeadsGanados) {
  const userTag = contactUsuario ? `, Usuario: "${contactUsuario}"` : '';
  clientContextPrefix = `[CLIENT CONTEXT: Existing customer in database (stage-leads-ganados). Full Name: "${contactName || 'Customer'}", Email: "${contactEmail || ''}", Phone: "${contactPhone || ''}", 1ra Compra: "${contactBio || ''}"${userTag}. RULES FOR THIS CLIENT: 1. NEVER proactively offer free trials. 2. If customer asks for a trial: check if for someone else in history, or confirm if for themselves (using registered data directly without re-asking) or for a family/friend (to collect recipient data). 3. If customer reports a technical issue or payment/account issue, DO NOT transfer immediately; perform technical or administrative triage first. 4. If customer explicitly asks for a human advisor, transfer without re-asking contact data.]\n\n`;
} else {
  const knownName = isValidPersonName ? contactName : '';
  const knownPhone = contactPhone ? contactPhone : '';
  let idInfo = [];
  if (knownName) idInfo.push(`Name: "${knownName}"`);
  if (knownPhone) idInfo.push(`Phone: "${knownPhone}"`);
  if (idInfo.length > 0) {
    clientContextPrefix = `[CLIENT CONTEXT: Known Contact info - ${idInfo.join(', ')}. (Note: For human transfer, customer Name and Phone must be known. If reporting issues or payments, perform technical/administrative triage first. If customer requests a free trial, collect full name with at least 2 words, email, and phone with country code)]\n\n`;
  }
}

return [{
  json: {
    conversation_id: conversationId,
    account_id: accountId,
    inbox_id: inboxId,
    contact_id: contactId,
    brand: brand,
    channel: channel,
    message: fullContent,
    content: historyBlock + clientContextPrefix + fullContent,
    raw_content: fullContent,
    contact_phone: contactPhone,
    contact_email: contactEmail,
    contact_name: contactName,
    contact_bio: contactBio,
    contact_additional_attributes: contactAdditionalAttrs,
    contact_custom_attributes: contactCustomAttrs,
    contact_company_name: contactCompanyName,
    contact_usuario: contactUsuario,
    labels: updatedLabels,
    already_leads_ganados: canBypassSheet,
    is_lead_ganado: isAlreadyLeadsGanados,
    is_human: isHuman,
    skip_ai_response: isHuman,
    has_image: hasImage,
    base64_image: base64Image,
    media_type: mediaType
  }
}];

const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

// 1. Extraer datos del nodo anterior o del input
let aiResponse = '';
try {
  aiResponse = $input.first().json.output || $input.first().json.text || $input.first().json.message || $input.first().json.content || '';
} catch (e) {
  aiResponse = '';
}

let prepData = {};
try {
  prepData = $('Preparar Mensaje').first().json || {};
} catch (e) {
  prepData = {};
}

let visionData = {};
try {
  visionData = $('Procesar Resultado Visión').first().json || {};
} catch (e) {
  try {
    visionData = $('Procesar Soporte TotalTv').first().json || {};
  } catch (e2) {
    visionData = {};
  }
}

const conversationId = prepData.conversation_id || visionData.conversation_id || $input.first().json.conversation_id || 13;
const accountId = prepData.account_id || visionData.account_id || $input.first().json.account_id || 1;
const inboxId = Number(prepData.inbox_id || visionData.inbox_id || $input.first().json.inbox_id || 0);
const channel = String(prepData.channel || visionData.channel || $input.first().json.channel || '');
const contactName = String(prepData.contact_name || visionData.contact_name || $input.first().json.contact_name || '').trim();
const contactPhone = String(prepData.contact_phone || visionData.contact_phone || $input.first().json.contact_phone || '').trim();
const contactEmail = String(prepData.contact_email || visionData.contact_email || $input.first().json.contact_email || '').trim();
const contactUsuario = String(prepData.contact_usuario || visionData.contact_usuario || $input.first().json.contact_usuario || '').trim();
const isTVTotal24 = (inboxId === 10 || inboxId === 13 || inboxId === 15 || inboxId === 16 || inboxId === 19);
const brandName = isTVTotal24 ? 'TVTotal24 (Latina)' : 'TotalTv USA';

let formattedText = String(aiResponse || '').trim();

// Detección precisa de idioma del cliente (español vs inglés)
const clientMessage = String(prepData.message || visionData.message || '').trim().toLowerCase();
const esRegex = /\b(hola|buen|buenos|buenas|dias|días|tardes|noches|gracias|amigo|precio|planes|cuenta|pago|renovaci[oó]n|mes|meses|dispositivo|por favor|ayuda|prueba|demo|servicio|activar|comprobante|listo|transferencia|aqui|ac[aá]|envi[eéo])\b/i;
const enRegex = /\b(hi|hello|hey|good|morning|afternoon|evening|thanks|thank you|price|plans|account|payment|renewal|month|months|device|devices|please|help|trial|demo|service|activate|receipt|done|transfer|here|sent)\b/i;

let isClientEnglish = false;
if (esRegex.test(clientMessage)) {
  isClientEnglish = false;
} else if (enRegex.test(clientMessage)) {
  isClientEnglish = true;
} else {
  // Si no hay palabras claras (ej. solo envió imagen sin texto), tvtotal24 es español, totaltvusa inglés por defecto
  const b = prepData.brand || visionData.brand || 'totaltvusa';
  isClientEnglish = (b === 'totaltvusa' && !isTVTotal24);
}

// Verificar si en esta ejecución se invocó la herramienta de transferencia
let transferToolCalled = false;
let transferReason = '';
let transferCaseDetails = '';
try {
  const toolNode = $('Call \'transfer_to_human_tool\'');
  if (toolNode) {
    const item = toolNode.first('ai_tool') || toolNode.first();
    if (item && item.json) {
      transferToolCalled = true;
      transferReason = String(item.json.reason || '');
      transferCaseDetails = String(item.json.case_details || '');
    }
  }
} catch (e) {}

// Detección de comprobante de pago o captura de error técnico
const isPaymentReceipt = Boolean(visionData.is_payment_receipt || prepData.is_payment_receipt) || /comprobante|pago|receipt/i.test(transferReason);
const isTechnicalScreenshot = Boolean(visionData.is_app_screenshot_or_error || prepData.is_app_screenshot_or_error) || /soporte t[eé]cnico|falla|error/i.test(transferReason);
const receiptData = visionData.receipt_data || prepData.receipt_data || {};

// A. Interceptar detenciones del motor de IA (max iterations, rate limit, errores internos o respuesta vacía)
const agentLimitRegex = /(?:agent stopped due to (?:max )?iterations?|iteration limit|time limit|max_iterations|maximum iterations|reached the maximum number of iterations|rate limit|rate_limit_exceeded|overloaded_error|too many requests|l[íi]mite m[aá]ximo de iteraciones|m[aá]ximo de iteraciones|m[aá]ximo de peticiones|detiene su funcionamiento por alcanzar un m[aá]ximo|l[íi]mite de peticiones|too many iterations)/i;

const isLimitError = !formattedText || agentLimitRegex.test(formattedText);

if (isLimitError) {
  if (isPaymentReceipt) {
    const method = (receiptData.payment_method || (transferReason.match(/\((.*?)\)/)?.[1]) || '').toUpperCase();
    const amt = receiptData.amount ? String(receiptData.amount).trim() : '';
    const curr = receiptData.currency ? String(receiptData.currency).trim() : '';
    const amountVal = (amt + ' ' + curr).trim();
    const refVal = receiptData.reference_number || '';

    let detailParts = [];
    if (method && method !== 'UNKNOWN' && method !== 'NONE') {
      detailParts.push(isClientEnglish ? `via ${method}` : `vía ${method}`);
    }
    if (amountVal) {
      const formattedAmt = amountVal.startsWith('$') ? amountVal : `$${amountVal}`;
      detailParts.push(isClientEnglish ? `for ${formattedAmt}` : `por ${formattedAmt}`);
    }
    if (refVal) {
      detailParts.push(`(Ref: ${refVal})`);
    }
    const detailStr = detailParts.length > 0 ? ` ${detailParts.join(' ')}` : '';

    if (isClientEnglish) {
      formattedText = `Thank you for sending your payment receipt! We have received your transaction details${detailStr}. I have transferred your case to our human administrative team to verify and process your activation/renewal shortly within our extended office hours. Thank you for your patience and preference!`;
    } else {
      formattedText = `¡Muchas gracias por enviar tu comprobante de pago! Hemos recibido los datos de tu transacción${detailStr}. He transferido tu caso a nuestro equipo administrativo para verificar la acreditación y procesar tu activación/renovación a la brevedad posible dentro de nuestro horario extendido de oficina. ¡Muchas gracias por tu paciencia y preferencia!`;
    }
  } else if (isTechnicalScreenshot) {
    const appName = (receiptData.app_name && receiptData.app_name !== 'Desconocida') ? receiptData.app_name : '';
    const appStrEs = appName ? ` con la aplicación ${appName}` : '';
    const appStrEn = appName ? ` with the ${appName} app` : '';
    if (isClientEnglish) {
      formattedText = `I have received the screenshot of your issue${appStrEn}. I have transferred your case along with the diagnostic details to our technical support team so an agent can assist you directly shortly within our extended office hours. Thank you for your patience!`;
    } else {
      formattedText = `He recibido la captura de tu pantalla${appStrEs}. He transferido tu caso junto con los detalles del diagnóstico a nuestro equipo de soporte técnico para que un asesor te asista directamente a la brevedad posible dentro de nuestro horario extendido de oficina. ¡Muchas gracias por tu paciencia!`;
    }
  } else if (isClientEnglish) {
    formattedText = "I have transferred your request to our human support team so an agent can assist you directly. An agent will assist you shortly within our extended office hours. Thank you for your patience!";
  } else {
    formattedText = "He transferido tu caso con nuestro equipo de soporte humano para que un asesor te atienda directamente. Un asesor te responderá a la brevedad posible dentro de nuestro horario extendido de oficina. ¡Muchas gracias por tu paciencia!";
  }
}

// B. Sanitizar posibles alucinaciones de fallo al transferir
const transferErrorRegex = /(?:inconveniente t[eé]cnico moment[aá]neo|no se pudo (?:hacer la )?transferencia|error al transferir|volver[eé] a intentar la transferencia|failed to transfer|momentary technical issue)/i;
if (transferErrorRegex.test(formattedText)) {
  if (isClientEnglish) {
    formattedText = "I have transferred your request to our human support team. An agent will assist you shortly within our extended office hours. Thank you for your patience!";
  } else {
    formattedText = "Te he transferido con nuestro equipo de soporte humano. Un asesor te atenderá a la brevedad posible dentro de nuestro horario extendido de oficina. ¡Muchas gracias por tu paciencia!";
  }
}

// C. Sanitizar fugas de procesos internos o errores de backend
const backendLeakRegex = /(?:no se (?:consiguieron|encontraron|hallaron|pudieron ubicar) (?:datos|credenciales|l[íi]neas?|registros?)(?: en (?:mvplay|mega\s*ott|el sistema|el panel|la base de datos))?|en mvplay|en mega\s*ott|en xtream|fall[oó] (?:la b[uú]squeda|el sistema|la consulta)|no fue posible ubicar (?:tus |sus )?credenciales autom[aá]ticamente)/i;
if (backendLeakRegex.test(formattedText)) {
  if (isClientEnglish) {
    formattedText = "I have transferred your request to our human support team so an agent can verify your access credentials and assist you directly. An agent will assist you shortly within our extended office hours. Thank you for your patience!";
  } else {
    formattedText = "He transferido tu caso con nuestro equipo de soporte humano para que un asesor verifique tus datos de acceso y te atienda directamente. Un asesor te responderá a la brevedad posible dentro de nuestro horario extendido de oficina. ¡Muchas gracias por tu paciencia!";
  }
}

// D. Si se llamó la tool de transferencia o hubo intención de transferencia, garantizar el aviso explícito
if (transferToolCalled) {
