// 2. Helpers robustos de búsqueda en Google Sheets
const getField = (obj, regex) => {
  if (!obj) return '';
  for (const k of Object.keys(obj)) {
    if (regex.test(k.trim())) {
      const v = obj[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
};

const cleanPhone = (raw) => {
  if (!raw) return '';
  let digits = String(raw).replace(/\D/g, '');
  if (digits.startsWith('00')) digits = digits.slice(2);
  return digits;
};

const normMex = (d) => (d.startsWith('521') && d.length === 13) ? ('52' + d.slice(3)) : d;

const phonesMatch = (p1, p2) => {
  const d1 = cleanPhone(p1);
  const d2 = cleanPhone(p2);
  if (!d1 || !d2 || d1.length < 7 || d2.length < 7) return false;

  if (d1 === d2) return true;
  if (d1.endsWith(d2) || d2.endsWith(d1)) return true;

  if (d1.length >= 10 && d2.length >= 10 && d1.slice(-10) === d2.slice(-10)) return true;
  if (d1.length >= 9 && d2.length >= 9 && d1.slice(-9) === d2.slice(-9)) return true;

  const m1 = normMex(d1);
  const m2 = normMex(d2);
  if (m1 === m2 || m1.endsWith(m2) || m2.endsWith(m1)) return true;
  if (m1.length >= 10 && m2.length >= 10 && m1.slice(-10) === m2.slice(-10)) return true;

  return false;
};

const emailsMatch = (e1, e2) => {
  if (!e1 || !e2) return false;
  const s1 = String(e1).trim().toLowerCase();
  const s2 = String(e2).trim().toLowerCase();
  return s1.includes('@') && s2.includes('@') && s1 === s2;
};

