const now = new Date();

let supportContextBlock = '';

if (rawDocText) {
  const lines = rawDocText.split('\n');
  let currentSection = '';
  let tecnicaRules = [];
  let administrativaRules = [];

  const monthNames = {
    'enero': 0, 'febrero': 1, 'marzo': 2, 'abril': 3, 'mayo': 4, 'junio': 5,
    'julio': 6, 'agosto': 7, 'septiembre': 8, 'octubre': 9, 'noviembre': 10, 'diciembre': 11
  };

  for (let line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    if (/^#*\s*t[eé]cnica/i.test(trimmed)) {
      currentSection = 'TECNICA';
      continue;
    } else if (/^#*\s*administrativa/i.test(trimmed)) {
      currentSection = 'ADMINISTRATIVA';
      continue;
    } else if (/^#*\s*consultas\s+pendientes/i.test(trimmed) || /^#*\s*sin\s+respuesta/i.test(trimmed)) {
      currentSection = 'PENDIENTES';
      continue;
    }

    if (currentSection === 'TECNICA' || currentSection === 'ADMINISTRATIVA') {
      let ruleText = trimmed.replace(/^[-*\d\.\)]\s*/, '').trim();
      const lowerRule = ruleText.toLowerCase();

      const isTvTotal24Tag = lowerRule.includes('tvtotal24') || lowerRule.includes('tvtotal 24') || lowerRule.includes('latina');
      const isTotalTvUsaTag = lowerRule.includes('totaltv usa') || lowerRule.includes('totaltvusa') || lowerRule.includes('totaltv_usa');

      if (isTvTotal24Tag && brand !== 'tvtotal24') continue;
      if (isTotalTvUsaTag && brand === 'tvtotal24') continue;

      const dateMatch = lowerRule.match(/antes\s+del?\s+(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)(?:\s+de\s+(\d{4}))?/i);
      if (dateMatch) {
        const day = parseInt(dateMatch[1]);
        const monthIndex = monthNames[dateMatch[2].toLowerCase()];
        const year = dateMatch[3] ? parseInt(dateMatch[3]) : now.getFullYear();
        const targetDate = new Date(year, monthIndex, day, 23, 59, 59);

        if (now > targetDate) {
          ruleText += ` (Condición temporal: Fecha límite ${day} de ${dateMatch[2]} trascendida).`;
        }
      }

      if (currentSection === 'TECNICA') {
        tecnicaRules.push(ruleText);
      } else {
        administrativaRules.push(ruleText);
      }
    }
  }

  if (tecnicaRules.length > 0 || administrativaRules.length > 0) {
    supportContextBlock = `[DOCUMENTO DE SOPORTE TOTALTV SUPPORT (BASE DE CONOCIMIENTO VIVA PARA ${brandName.toUpperCase()}):\n`;
    if (tecnicaRules.length > 0) {
      supportContextBlock += `--- SECCIÓN TÉCNICA ---\n` + tecnicaRules.map(r => `• ${r}`).join('\n') + '\n';
    }
    if (administrativaRules.length > 0) {
      supportContextBlock += `--- SECCIÓN ADMINISTRATIVA ---\n` + administrativaRules.map(r => `• ${r}`).join('\n') + '\n';
    }
    supportContextBlock += `INSTRUCCIONES DE MÁXIMA PRIORIDAD PARA EL AGENTE DE IA:\n`;
    supportContextBlock += `1. Si la situación reportada por el cliente coincide con alguna de las instrucciones anteriores, APLICA DIRECTAMENTE LA SOLUCIÓN INDICADA EN EL DOCUMENTO para ayudar al cliente sin preguntas adicionales innecesarias.\n`;
    supportContextBlock += `2. NO realices transferencias a humano prematuras ni hagas preguntas genéricas cuando las instrucciones anteriores resuelven el caso.\n`;
    supportContextBlock += `3. Si logras resolver la situación del cliente con esta información, NO es necesario transferir a un asesor humano.\n`;
    supportContextBlock += `4. Si la situación del cliente NO está contemplada aquí ni en tu prompt y requiere atención personalizada, realiza la transferencia con Call 'transfer_to_human_tool'.]\n\n`;
  }
}

